UPDATE growth_autopilot_task
SET
    status = 'superseded',
    update_time = NOW()
WHERE goal_id = #{goalId}
  AND user_id = #{userId}
  AND status = 'todo'
  AND task_date >= #{date}

UPDATE growth_autopilot_task
SET
    status = 'superseded',
    plan_version = #{planVersion},
    selection_reason = #{selectionReason},
    update_time = NOW()
WHERE id = #{id}
  AND goal_id = #{goalId}
  AND user_id = #{userId}
  AND status = 'todo'
